import { world, system, PlayerPermissionLevel } from "@minecraft/server";
import { CustomForm as MinecraftCustomForm, MessageFormData, ObservableString, ObservableBoolean, ObservableNumber } from "@minecraft/server-ui";

// DDUI buttons do not automatically dismiss a CustomForm. Wrap the stable API so every
// button explicitly closes its current form and defers its handler out of the UI callback.
// This prevents the visible form from sitting on-screen and intercepting subsequent menus.
class CustomForm extends MinecraftCustomForm {
  button(label, onClick, options) {
    const buttonLabel = typeof label === "string" ? label.replace(/§./g, "") : label;
    return super.button(buttonLabel, () => {
      try { this.close(); } catch {}
      system.run(() => {
        try { onClick(); } catch (e) { console.warn(`[Transfer UI] button handler failed: ${e?.stack ?? e}`); }
      });
    }, options);
  }
}

import { transferPlayer, variables } from "@minecraft/server-admin";


const PACK="Transfer UI", DATA_KEY="transferhub:data", BACKUP_KEY="transferhub:backup", DRAFT_KEY="transferhub:draft", AUDIT_KEY="transferhub:audit";
const FAV_KEY="transferhub:favorites", PREF_KEY="transferhub:prefs", HISTORY_KEY="transferhub:history";
const DATA_VERSION=4, MAX_NODES=180, MAX_AUDIT=80;
const BSM_CACHE_KEY="transferhub:bsmcache", BSM_SELF_KEY="transferhub:bsmself", BSM_WS_KEY="transferhub:bsmws";
const DEF={version:DATA_VERSION,revision:1,settings:{title:"§b§lServer Network",subtitle:"Choose a destination.",openerItem:"minecraft:compass",showDirectConnect:false,confirmTransfers:true,maxRecent:8},nodes:[{id:"main",type:"folder",parentId:null,name:"Main Servers",description:"Official network destinations",order:0,enabled:true}],announcements:[]};
const clone=v=>JSON.parse(JSON.stringify(v));
const parse=(v,f)=>{try{return typeof v==="string"?JSON.parse(v):f}catch{return f}};
const clean=s=>`${s??""}`.trim();
const idFrom=s=>clean(s).toLowerCase().replace(/§./g,"").replace(/[^a-z0-9_-]+/g,"-").replace(/^-+|-+$/g,"").slice(0,32)||`node-${Date.now()}`;
const unique=(items,want)=>{let x=want,n=2;const u=new Set(items.map(v=>v.id));while(u.has(x))x=`${want}-${n++}`;return x};
const later=fn=>system.run(fn), info=(p,m)=>p.sendMessage(`§a[Transfer UI] ${m}`), err=(p,m)=>p.sendMessage(`§c[Transfer UI] ${m}`);
const isAdmin=p=>{try{return p.playerPermissionLevel===PlayerPermissionLevel.Operator}catch{return false}};
function normalize(raw){const d=raw&&typeof raw==="object"?raw:clone(DEF);if(Array.isArray(d.categories)||Array.isArray(d.servers)){const nodes=[];for(const c of d.categories??[])nodes.push({id:c.id,type:"folder",parentId:null,name:c.name,description:c.description??"",order:c.order??0,enabled:true});for(const s of d.servers??[])nodes.push({...s,type:"server",parentId:s.categoryId??"main",tags:s.tags??[],region:s.region??"",gameMode:s.gameMode??"",recommended:!!s.recommended,maintenance:!!s.maintenance,requirements:s.requirements??{}});d.nodes=nodes;delete d.categories;delete d.servers}d.version=DATA_VERSION;d.revision=Number(d.revision)||1;d.settings={...DEF.settings,...(d.settings??{})};d.nodes=Array.isArray(d.nodes)?d.nodes:clone(DEF.nodes);d.announcements=Array.isArray(d.announcements)?d.announcements:[];if(!d.nodes.some(n=>n.type==="folder"))d.nodes.unshift(clone(DEF.nodes[0]));for(const n of d.nodes){n.id=n.id||unique(d.nodes,idFrom(n.name));n.type=["folder","server","info"].includes(n.type)?n.type:"info";n.parentId=n.parentId??null;n.name=n.name||"Untitled";n.description=n.description??"";n.order=Number(n.order)||0;n.enabled=n.enabled!==false;if(n.type==="server"){n.tags=Array.isArray(n.tags)?n.tags:[];n.requirements=n.requirements&&typeof n.requirements==="object"?n.requirements:{};n.cooldownSeconds=Math.max(0,Number(n.cooldownSeconds)||0)}}return d}
function getPublished(){return normalize(parse(world.getDynamicProperty(DATA_KEY),clone(DEF)))}
function savePublished(d,actor="system",action="publish"){const next=normalize(d),text=JSON.stringify(next);if(text.length>30000)throw Error("Configuration exceeds 30,000 characters.");const old=world.getDynamicProperty(DATA_KEY);if(typeof old==="string")world.setDynamicProperty(BACKUP_KEY,old);world.setDynamicProperty(DATA_KEY,text);audit(actor,action,`revision ${next.revision}`)}
function getDraft(){const v=world.getDynamicProperty(DRAFT_KEY);return typeof v==="string"?normalize(parse(v,getPublished())):clone(getPublished())}
function saveDraft(d){const t=JSON.stringify(normalize(d));if(t.length>30000)throw Error("Draft exceeds 30,000 characters.");world.setDynamicProperty(DRAFT_KEY,t)}
function audit(actor,action,detail=""){const a=parse(world.getDynamicProperty(AUDIT_KEY),[]);a.unshift({time:new Date().toISOString(),actor:typeof actor==="string"?actor:actor?.name??"system",action,detail});world.setDynamicProperty(AUDIT_KEY,JSON.stringify(a.slice(0,MAX_AUDIT)))}
function pjson(p,key,f){return parse(p.getDynamicProperty(key),clone(f))}function pset(p,key,v){p.setDynamicProperty(key,JSON.stringify(v))}
const favs=p=>pjson(p,FAV_KEY,[]);const prefs=p=>({...{home:null,confirmMode:"default"},...pjson(p,PREF_KEY,{})});const hist=p=>pjson(p,HISTORY_KEY,[]);
function visible(p,n){if(n.enabled===false)return false;if(n.type==="server"&&n.bsm?.serverName&&n.bsm.serverName===getBsmSelf())return false;const r=n.requirements??{};if(r.adminOnly&&!isAdmin(p))return false;if(r.tag&&!p.hasTag(r.tag))return false;if(r.notTag&&p.hasTag(r.notTag))return false;if(r.dimension&&p.dimension?.id!==r.dimension)return false;if(r.scoreObjective){try{const o=world.scoreboard.getObjective(r.scoreObjective);const s=o?.getScore(p.scoreboardIdentity);if(s===undefined)return false;if(r.minScore!==undefined&&s<Number(r.minScore))return false;if(r.maxScore!==undefined&&s>Number(r.maxScore))return false}catch{return false}}return true}
function children(data,parent,p){return data.nodes.filter(n=>(n.parentId??null)===(parent??null)&&visible(p,n)).sort((a,b)=>(a.order??0)-(b.order??0)||a.name.localeCompare(b.name))}
function recordVisit(p,id){const d=getPublished(),max=d.settings.maxRecent??8;const h=hist(p).filter(x=>x.id!==id);h.unshift({id,time:Date.now()});pset(p,HISTORY_KEY,h.slice(0,max));const pr=prefs(p);pr.last=id;pset(p,PREF_KEY,pr)}
const cooldowns=new Map();
function doTransfer(p,n){try{const k=`${p.id}:${n.id}`,now=Date.now(),until=cooldowns.get(k)??0;if(now<until)return err(p,`Please wait ${Math.ceil((until-now)/1000)}s before using this destination again.`);cooldowns.set(k,now+(n.cooldownSeconds??2)*1000);recordVisit(p,n.id);if(n.netherNetId)transferPlayer(p,{netherNetId:n.netherNetId});else{const port=Number(n.port);if(!n.hostname||!Number.isInteger(port)||port<1||port>65535)throw Error("Invalid hostname or port.");transferPlayer(p,{hostname:n.hostname,port})}info(p,`Connecting to ${n.name}...`)}catch(e){err(p,`Transfer failed: ${e?.message??e}`)}}
function connect(p,n){if(n.maintenance&&!isAdmin(p))return err(p,"This destination is currently in maintenance mode.");const pr=prefs(p),confirm=pr.confirmMode==="always"||(pr.confirmMode==="default"&&getPublished().settings.confirmTransfers);if(!confirm)return doTransfer(p,n);new MessageFormData().title("§b§lConfirm Transfer").body(`Connect to ${n.name}?${n.maintenance?"\n§eMaintenance mode is enabled.":""}`).button1("Connect").button2("Cancel").show(p).then(r=>{if(!r.canceled&&r.selection===0)doTransfer(p,n)}).catch(e=>console.warn(`[${PACK}] confirm transfer UI failed: ${e}`))}
function nodeDetail(p,n,parent){const f=favs(p),pr=prefs(p),isFav=f.includes(n.id);const form=new CustomForm(p,n.name).label(n.description||"No description");if(n.type==="server"){const meta=[n.gameMode,n.region,...(n.tags??[])].filter(Boolean).join(" • ");if(meta)form.label(`§7${meta}`);if(n.announcement)form.label(`§e${n.announcement}`);if(n.bsm?.serverName){const c=getBsmCache(n.bsm.serverName);form.label(c?`§bBSM: §f${c.status??"Unknown"} §8• §f${c.player_count??0} player(s) §8• §7${c.version??""}`:`§7BSM: status not cached`)}form.divider().button(n.maintenance?"Connect (Maintenance)":"Connect",()=>connect(p,n));if(n.bsm?.serverName)form.button("Refresh BSM Status",()=>refreshBsmNode(p,n,parent));form.button(isFav?"Remove Favorite":"Add Favorite",()=>{let a=favs(p);a=isFav?a.filter(x=>x!==n.id):[...new Set([...a,n.id])];pset(p,FAV_KEY,a);later(()=>nodeDetail(p,n,parent))}).button(pr.home===n.id?"Clear Home":"Set Home",()=>{const x=prefs(p);x.home=x.home===n.id?null:n.id;pset(p,PREF_KEY,x);later(()=>nodeDetail(p,n,parent))})}else if(n.type==="folder")form.divider().button("Open",()=>later(()=>showFolder(p,n.id)));form.divider().button("Back",()=>later(()=>showFolder(p,parent))).closeButton().show().catch(e=>console.warn(`[${PACK}] DDUI show failed: ${e}`))}
function addNodeButton(form,p,n,parent){const c=n.type==="server"&&n.bsm?.serverName?getBsmCache(n.bsm.serverName):null;let desc=n.description?`\n${n.description.slice(0,62)}`:"";if(c){const running=`${c.status??""}`.toLowerCase()==="running";desc=`\n${running?"Online":"Offline"} • ${c.player_count??0} player(s)${n.description?` • ${n.description.slice(0,34)}`:""}`;}form.button(`${n.name}${desc}`,()=>later(()=>n.type==="folder"?showFolder(p,n.id):nodeDetail(p,n,parent)))}
function breadcrumb(data,parent){const names=[];let id=parent,guard=0;while(id&&guard++<12){const n=data.nodes.find(x=>x.id===id);if(!n)break;names.unshift(n.name);id=n.parentId??null}return names.length?`Network / ${names.join(" / ")}`:"Network"}
function showFolder(p,parent=null){const d=getPublished(),parentNode=parent?d.nodes.find(n=>n.id===parent):null;const form=new CustomForm(p,parentNode?.name??d.settings.title).label(parentNode?.description??d.settings.subtitle);if(parent)form.label(`§8${breadcrumb(d,parent)}`);if(!parent){for(const a of d.announcements.filter(x=>x.enabled!==false).slice(0,3))form.label(`§e${a.title}: §f${a.text}`);form.divider().header("§b§lQuick Access").button("Favorites",()=>later(()=>showSpecial(p,"favorites"))).button("Recent",()=>later(()=>showSpecial(p,"recent")));const pr=prefs(p);if(pr.home&&d.nodes.some(n=>n.id===pr.home&&visible(p,n)))form.button("Home Server",()=>later(()=>nodeDetail(p,d.nodes.find(n=>n.id===pr.home),null)));form.button("Search",()=>later(()=>showSearch(p))).divider().header("§a§lNetwork Destinations");}
const list=children(d,parent,p);for(const n of list)addNodeButton(form,p,n,parent);if(!list.length)form.label("§7No destinations in this section.");form.divider();if(parent)form.button("Back",()=>later(()=>showFolder(p,parentNode?.parentId??null)));if(!parent&&d.settings.showDirectConnect)form.button("Manual Connection",()=>later(()=>showDirect(p)));if(!parent&&isAdmin(p))form.button("Admin Navigation",()=>later(()=>showAdmin(p)));form.closeButton().show().catch(e=>console.warn(`[${PACK}] DDUI show failed: ${e}`))}
function showSpecial(p,mode){const d=getPublished();let nodes=[];if(mode==="favorites"){const s=new Set(favs(p));nodes=d.nodes.filter(n=>n.type==="server"&&s.has(n.id)&&visible(p,n))}else{const map=new Map(d.nodes.map(n=>[n.id,n]));nodes=hist(p).map(h=>map.get(h.id)).filter(n=>n&&n.type==="server"&&visible(p,n))}const form=new CustomForm(p,mode==="favorites"?"§e§lFavorites":"§b§lRecent").label(`${nodes.length} destination(s)`).divider();for(const n of nodes)addNodeButton(form,p,n,null);if(!nodes.length)form.label("§7Nothing here yet.");form.divider().button("§7Back",()=>later(()=>showFolder(p))).closeButton().show().catch(e=>console.warn(`[${PACK}] DDUI show failed: ${e}`))}
function showSearch(p){const q=new ObservableString("",{clientWritable:true});new CustomForm(p,"§b§lSearch Servers").textField("Name, tag, region, or game mode",q).button("Search",()=>{const term=clean(q.getData()).toLowerCase(),d=getPublished();const hits=d.nodes.filter(n=>n.type==="server"&&visible(p,n)&&[n.name,n.description,n.region,n.gameMode,...(n.tags??[])].join(" ").toLowerCase().includes(term)).slice(0,30);const f=new CustomForm(p,`Search: ${term||"all"}`).label(`${hits.length} result(s)`).divider();for(const n of hits)addNodeButton(f,p,n,null);f.divider().button("§7Back",()=>later(()=>showFolder(p))).closeButton().show().catch(e=>console.warn(`[${PACK}] DDUI show failed: ${e}`))}).button("§7Back",()=>later(()=>showFolder(p))).closeButton().show().catch(e=>console.warn(`[${PACK}] DDUI show failed: ${e}`))}
function showDirect(p){const net=new ObservableBoolean(false,{clientWritable:true}),addr=new ObservableString("",{clientWritable:true}),port=new ObservableString("19132",{clientWritable:true});new CustomForm(p,"§b§lManual Connection").header("§b§lConnect to a Server").label("§7Enter a normal Bedrock hostname/IP and port, or enable NetherNet and enter a NetherNet ID.").toggle("Use NetherNet",net).textField("IP / Hostname / NetherNet ID",addr).textField("Port (IP / hostname only)",port).divider().button("Connect",()=>{const a=clean(addr.getData());if(!a)return err(p,"Enter an IP, hostname, or NetherNet ID.");if(net.getData())return connect(p,{id:"manual-nethernet",name:a,netherNetId:a});const po=Number(port.getData());if(!Number.isInteger(po)||po<1||po>65535)return err(p,"Port must be between 1 and 65535.");connect(p,{id:"manual-ip",name:`${a}:${po}`,hostname:a,port:po})}).button("Back",()=>later(()=>showFolder(p))).closeButton().show().catch(e=>console.warn(`[${PACK}] DDUI show failed: ${e}`))}
function showAdmin(p){if(!isAdmin(p))return;const pub=getPublished(),draft=getDraft();new CustomForm(p,"§c§lTransfer UI Admin").header("§aDestination Management").label("§7Add servers here, organize them into folders, then publish the draft when ready.").label(`§fPublished revision: §a${pub.revision}  §8•  §fDraft items: §e${draft.nodes.length}`).divider().button("+ Add Destination",()=>later(()=>adminEditNode(p,null,null,"server"))).button("+ Add Navigation Folder",()=>later(()=>adminEditNode(p,null,null,"folder"))).button("Manage Destinations & Navigation",()=>later(()=>adminNodes(p,null))).divider().header("§bBedrock Server Manager").label("§7Discover BSM 4.x servers, view live state, and sync destinations into the draft.").button("BSM Network",()=>later(()=>showBsmAdmin(p))).divider().header("§bNetwork Configuration").button("Announcements",()=>later(()=>adminAnnouncements(p))).button("Hub Settings",()=>later(()=>adminSettings(p))).button("Player Preferences",()=>later(()=>playerSettings(p))).divider().header("§eDraft & Publishing").label("§7Changes are private until Publish Draft is used.").button("Publish Draft",()=>later(()=>confirmPublish(p))).button("Export / Import",()=>later(()=>adminTransferConfig(p))).button("Audit Log",()=>later(()=>adminAudit(p))).button("Restore Backup",()=>later(()=>restoreBackup(p))).divider().button("Back to Server Network",()=>later(()=>showFolder(p))).closeButton().show().catch(e=>console.warn(`[${PACK}] DDUI show failed: ${e}`))}
function adminNodes(p,parent){const d=getDraft(),par=parent?d.nodes.find(n=>n.id===parent):null,form=new CustomForm(p,par?`Edit: ${par.name}`:"§lDraft Destinations").header(par?`§bFolder: §f${par.name}`:"§aDestinations & Navigation").label("§7Select an existing item to edit it, or use the add buttons below. Servers placed at the root appear directly on the main menu; folders can contain more folders, servers, and info pages.").divider();for(const n of d.nodes.filter(n=>(n.parentId??null)===(parent??null)).sort((a,b)=>a.order-b.order))form.button(`${n.name}`,()=>later(()=>n.type==="folder"?adminFolderActions(p,n.id):adminEditNode(p,n.id,parent)));form.divider().button("§a+ Add Folder",()=>later(()=>adminEditNode(p,null,parent,"folder"))).button("§a+ Add Server",()=>later(()=>adminEditNode(p,null,parent,"server"))).button("§a+ Add Info",()=>later(()=>adminEditNode(p,null,parent,"info"))).button("§7Back",()=>later(()=>parent?adminNodes(p,par?.parentId??null):showAdmin(p))).closeButton().show().catch(e=>console.warn(`[${PACK}] DDUI show failed: ${e}`))}
function adminFolderActions(p,id){const d=getDraft(),n=d.nodes.find(x=>x.id===id);new CustomForm(p,n.name).button("Open Children",()=>later(()=>adminNodes(p,id))).button("Edit Folder",()=>later(()=>adminEditNode(p,id,n.parentId))).button("§7Back",()=>later(()=>adminNodes(p,n.parentId))).closeButton().show().catch(e=>console.warn(`[${PACK}] DDUI show failed: ${e}`))}
function adminEditNode(p,id,parent,type){if(!isAdmin(p))return;const d=getDraft(),e=d.nodes.find(n=>n.id===id),kind=e?.type??type??"info";const name=new ObservableString(e?.name??"",{clientWritable:true}),desc=new ObservableString(e?.description??"",{clientWritable:true}),order=new ObservableString(`${e?.order??0}`,{clientWritable:true}),enabled=new ObservableBoolean(e?.enabled!==false,{clientWritable:true});const form=new CustomForm(p,e?`Edit: ${e.name}`:`Add ${kind}`).textField("Name",name).textField("Description",desc).textField("Sort Order",order).toggle("Enabled",enabled);let host,port,nether,tags,region,game,reco,maint,announce,cool,tag,notTag,dim,obj,min,max;if(kind==="server"){host=new ObservableString(e?.hostname??"",{clientWritable:true});port=new ObservableString(`${e?.port??19132}`,{clientWritable:true});nether=new ObservableString(e?.netherNetId??"",{clientWritable:true});tags=new ObservableString((e?.tags??[]).join(", "),{clientWritable:true});region=new ObservableString(e?.region??"",{clientWritable:true});game=new ObservableString(e?.gameMode??"",{clientWritable:true});reco=new ObservableBoolean(!!e?.recommended,{clientWritable:true});maint=new ObservableBoolean(!!e?.maintenance,{clientWritable:true});announce=new ObservableString(e?.announcement??"",{clientWritable:true});cool=new ObservableString(`${e?.cooldownSeconds??2}`,{clientWritable:true});form.divider().textField("Hostname / IP",host).textField("Port",port).textField("NetherNet ID (overrides hostname)",nether).textField("Tags (comma separated)",tags).textField("Region",region).textField("Game Mode",game).toggle("Recommended",reco).toggle("Maintenance",maint).textField("Destination Notice",announce).textField("Cooldown Seconds",cool)}tag=new ObservableString(e?.requirements?.tag??"",{clientWritable:true});notTag=new ObservableString(e?.requirements?.notTag??"",{clientWritable:true});dim=new ObservableString(e?.requirements?.dimension??"",{clientWritable:true});obj=new ObservableString(e?.requirements?.scoreObjective??"",{clientWritable:true});min=new ObservableString(e?.requirements?.minScore!==undefined?`${e.requirements.minScore}`:"",{clientWritable:true});max=new ObservableString(e?.requirements?.maxScore!==undefined?`${e.requirements.maxScore}`:"",{clientWritable:true});const adminOnly=new ObservableBoolean(!!e?.requirements?.adminOnly,{clientWritable:true});form.divider().label("Visibility Requirements").textField("Required Tag",tag).textField("Excluded Tag",notTag).textField("Dimension ID",dim).textField("Scoreboard Objective",obj).textField("Minimum Score",min).textField("Maximum Score",max).toggle("Operators Only",adminOnly).divider().button("§aSave Draft",()=>{try{const cur=getDraft(),nm=clean(name.getData());if(!nm)return err(p,"Name is required.");if(!e&&cur.nodes.length>=MAX_NODES)return err(p,`Node limit is ${MAX_NODES}.`);let t=e?cur.nodes.find(n=>n.id===id):{id:unique(cur.nodes,idFrom(nm)),type:kind,parentId:parent??null};if(!t)return;t.name=nm;t.description=clean(desc.getData());t.order=Number(order.getData())||0;t.enabled=enabled.getData();t.requirements={tag:clean(tag.getData()),notTag:clean(notTag.getData()),dimension:clean(dim.getData()),scoreObjective:clean(obj.getData()),adminOnly:adminOnly.getData()};if(clean(min.getData())!=="")t.requirements.minScore=Number(min.getData());if(clean(max.getData())!=="")t.requirements.maxScore=Number(max.getData());if(kind==="server"){t.hostname=clean(host.getData());t.port=Number(port.getData())||19132;t.netherNetId=clean(nether.getData());if(!t.netherNetId&&!t.hostname)return err(p,"Hostname or NetherNet ID is required.");t.tags=tags.getData().split(",").map(clean).filter(Boolean);t.region=clean(region.getData());t.gameMode=clean(game.getData());t.recommended=reco.getData();t.maintenance=maint.getData();t.announcement=clean(announce.getData());t.cooldownSeconds=Math.max(0,Number(cool.getData())||0)}if(!e)cur.nodes.push(t);saveDraft(cur);audit(p,"draft-save",`${kind} ${nm}`);info(p,`Saved ${nm} to draft.`);later(()=>adminNodes(p,parent))}catch(x){err(p,x?.message??x)}});if(e)form.button("§cDelete",()=>later(()=>confirmDeleteNode(p,id,parent)));form.button("§7Cancel",()=>later(()=>adminNodes(p,parent))).closeButton().show().catch(e=>console.warn(`[${PACK}] DDUI show failed: ${e}`))}
function confirmDeleteNode(p,id,parent){const d=getDraft(),n=d.nodes.find(x=>x.id===id);if(!n)return;new MessageFormData().title("Delete Draft Item").body(`Delete ${n.name} and all of its children?`).button1("Delete").button2("Cancel").show(p).then(r=>{if(!r.canceled&&r.selection===0){const ids=new Set([id]);let changed=true;while(changed){changed=false;for(const x of d.nodes)if(x.parentId&&ids.has(x.parentId)&&!ids.has(x.id)){ids.add(x.id);changed=true}}d.nodes=d.nodes.filter(x=>!ids.has(x.id));saveDraft(d);audit(p,"draft-delete",n.name)}later(()=>adminNodes(p,parent))}).catch(e=>console.warn(`[${PACK}] delete confirmation UI failed: ${e}`))}
function adminSettings(p){const d=getDraft(),s=d.settings,title=new ObservableString(s.title,{clientWritable:true}),sub=new ObservableString(s.subtitle,{clientWritable:true}),open=new ObservableString(s.openerItem,{clientWritable:true}),direct=new ObservableBoolean(s.showDirectConnect,{clientWritable:true}),confirm=new ObservableBoolean(s.confirmTransfers,{clientWritable:true}),recent=new ObservableString(`${s.maxRecent}`,{clientWritable:true});new CustomForm(p,"Draft Hub Settings").textField("Title",title).textField("Subtitle",sub).textField("Opener Item",open).toggle("Allow Players to Use Manual Connection",direct).toggle("Confirm Transfers by Default",confirm).textField("Recent History Size",recent).button("§aSave Draft",()=>{const x=getDraft();x.settings={...x.settings,title:clean(title.getData())||DEF.settings.title,subtitle:clean(sub.getData()),openerItem:clean(open.getData())||"minecraft:compass",showDirectConnect:direct.getData(),confirmTransfers:confirm.getData(),maxRecent:Math.max(1,Math.min(20,Number(recent.getData())||8))};saveDraft(x);audit(p,"draft-settings");later(()=>showAdmin(p))}).button("§7Cancel",()=>later(()=>showAdmin(p))).closeButton().show().catch(e=>console.warn(`[${PACK}] DDUI show failed: ${e}`))}
function playerSettings(p){const pr=prefs(p),idx=["default","always","never"].indexOf(pr.confirmMode),mode=new ObservableNumber(Math.max(0,idx),{clientWritable:true});new CustomForm(p,"§b§lPlayer Preferences").dropdown("Transfer Confirmation",mode,[{label:"Use Network Default",value:0},{label:"Always Confirm",value:1},{label:"Never Confirm",value:2}]).button("Save",()=>{const x=prefs(p);x.confirmMode=["default","always","never"][mode.getData()]??"default";pset(p,PREF_KEY,x);later(()=>showAdmin(p))}).button("Back",()=>later(()=>showAdmin(p))).closeButton().show().catch(e=>console.warn(`[${PACK}] DDUI show failed: ${e}`))}
function adminAnnouncements(p){const d=getDraft(),form=new CustomForm(p,"§e§lAnnouncements").label("Published with the draft.").divider();for(const a of d.announcements)form.button(`${a.enabled===false?"§8":"§e"}${a.title}`,()=>later(()=>editAnnouncement(p,a.id)));form.divider().button("§a+ Add Announcement",()=>later(()=>editAnnouncement(p))).button("§7Back",()=>later(()=>showAdmin(p))).closeButton().show().catch(e=>console.warn(`[${PACK}] DDUI show failed: ${e}`))}
function editAnnouncement(p,id){const d=getDraft(),e=d.announcements.find(a=>a.id===id),title=new ObservableString(e?.title??"",{clientWritable:true}),text=new ObservableString(e?.text??"",{clientWritable:true}),enabled=new ObservableBoolean(e?.enabled!==false,{clientWritable:true});const f=new CustomForm(p,e?"Edit Announcement":"Add Announcement").textField("Title",title).textField("Message",text).toggle("Enabled",enabled).button("Save Draft",()=>{const x=getDraft(),t=e?x.announcements.find(a=>a.id===id):{id:unique(x.announcements,idFrom(title.getData()))};t.title=clean(title.getData());t.text=clean(text.getData());t.enabled=enabled.getData();if(!e)x.announcements.push(t);saveDraft(x);audit(p,"draft-announcement",t.title);later(()=>adminAnnouncements(p))});if(e)f.button("§cDelete",()=>{const x=getDraft();x.announcements=x.announcements.filter(a=>a.id!==id);saveDraft(x);later(()=>adminAnnouncements(p))});f.button("Back",()=>later(()=>adminAnnouncements(p))).closeButton().show().catch(e=>console.warn(`[${PACK}] DDUI show failed: ${e}`))}
function confirmPublish(p){new MessageFormData().title("Publish Draft").body("Publish the current draft to every player? The existing published config will be backed up first.").button1("Publish").button2("Cancel").show(p).then(r=>{if(!r.canceled&&r.selection===0){const d=getDraft();d.revision=(getPublished().revision??0)+1;savePublished(d,p,"publish");world.setDynamicProperty(DRAFT_KEY,JSON.stringify(d));info(p,`Published revision ${d.revision}.`)}later(()=>showAdmin(p))}).catch(e=>console.warn(`[${PACK}] publish confirmation UI failed: ${e}`))}
function restoreBackup(p){const b=world.getDynamicProperty(BACKUP_KEY);if(typeof b!=="string")return err(p,"No backup exists yet.");new MessageFormData().title("Restore Backup").body("Replace the published configuration with the previous backup?").button1("Restore").button2("Cancel").show(p).then(r=>{if(!r.canceled&&r.selection===0){const current=world.getDynamicProperty(DATA_KEY);world.setDynamicProperty(DATA_KEY,b);if(typeof current==="string")world.setDynamicProperty(BACKUP_KEY,current);world.setDynamicProperty(DRAFT_KEY,b);audit(p,"restore-backup");info(p,"Backup restored.")}later(()=>showAdmin(p))}).catch(e=>console.warn(`[${PACK}] restore confirmation UI failed: ${e}`))}
function adminTransferConfig(p){const input=new ObservableString("",{clientWritable:true});new CustomForm(p,"§b§lExport / Import").label("Export is printed to chat. Paste JSON below to import it into the DRAFT only.").button("§eExport Published to Chat",()=>{p.sendMessage(`§7[Transfer UI Export]\n${JSON.stringify(getPublished())}`)}).textField("Import JSON",input).button("§aImport to Draft",()=>{try{const raw=parse(input.getData(),null);if(!raw)throw Error("Invalid JSON.");const d=normalize(raw);saveDraft(d);audit(p,"import-draft",`${d.nodes.length} nodes`);info(p,"Imported configuration into draft. Review it before publishing.");later(()=>showAdmin(p))}catch(e){err(p,e?.message??e)}}).button("§7Back",()=>later(()=>showAdmin(p))).closeButton().show().catch(e=>console.warn(`[${PACK}] DDUI show failed: ${e}`))}
function adminAudit(p){const a=parse(world.getDynamicProperty(AUDIT_KEY),[]),f=new CustomForm(p,"§e§lAudit Log").label("Newest changes first.").divider();for(const x of a.slice(0,25))f.label(`§7${x.time} §f${x.actor} §e${x.action} §7${x.detail??""}`);f.divider().button("§7Back",()=>later(()=>showAdmin(p))).closeButton().show().catch(e=>console.warn(`[${PACK}] DDUI show failed: ${e}`))}
const bsmApiState={available:false,state:"unknown",authenticated:false,lastError:"",baseUrl:"",wsUrl:"",operationCount:0};
const bsmPending=new Map(),bsmChunks=new Map();let bsmReqSeq=0;
function bsmTransferHost(){return clean(variables.get("transferuiBsmTransferHost")??"127.0.0.1")}
function bsmConfig(){return {url:bsmApiState.baseUrl||"BSM API addon",host:bsmTransferHost(),hasCredentials:bsmApiState.available,authenticated:bsmApiState.authenticated}}
function sendChunked(id,payload,requestId){const s=JSON.stringify(payload),size=1400,total=Math.max(1,Math.ceil(s.length/size));for(let i=0;i<total;i++)system.sendScriptEvent(id,JSON.stringify({id:requestId,chunk:i,total,data:s.slice(i*size,(i+1)*size)}))}
function receiveBsmChunk(kind,message){let p;try{p=JSON.parse(message)}catch{return null};const key=`${kind}:${p.id??"global"}`,x=bsmChunks.get(key)??{parts:new Array(p.total),time:Date.now()};x.parts[p.chunk]=p.data;bsmChunks.set(key,x);if(x.parts.filter(v=>v!==undefined).length!==p.total)return null;bsmChunks.delete(key);try{return JSON.parse(x.parts.join(""))}catch{return null}}
async function bsmCall(operationId,args={}){const id=`tui-${Date.now()}-${++bsmReqSeq}`;return new Promise((resolve,reject)=>{const timeout=system.runTimeout(()=>{bsmPending.delete(id);reject(Error("BSM API addon request timed out"))},300);bsmPending.set(id,{resolve,reject,timeout});sendChunked("bsmapi:request",{operationId,args},id)})}
function asList(x){if(Array.isArray(x))return x;if(Array.isArray(x?.items))return x.items;if(Array.isArray(x?.data))return x.data;if(Array.isArray(x?.players))return x.players;if(Array.isArray(x?.backups))return x.backups;if(Array.isArray(x?.addons))return x.addons;return []}
function getBsmCache(name){const c=parse(world.getDynamicProperty(BSM_CACHE_KEY),{});return c[name]}
function putBsmCache(items){const c=parse(world.getDynamicProperty(BSM_CACHE_KEY),{});for(const x of items??[])if(x?.name)c[x.name]={...c[x.name],...x,updated:Date.now()};world.setDynamicProperty(BSM_CACHE_KEY,JSON.stringify(c))}
async function fetchBsmServers(){const x=await bsmCall("get_servers_list_api_servers_get");const list=Array.isArray(x?.servers)?x.servers:[];putBsmCache(list);return list}
async function fetchBsmProperties(name){const x=await bsmCall("get_properties_api_server__server_name__properties_get_get",{path:{server_name:name}});return x?.properties??{}}
async function refreshBsmNode(p,n,parent){try{info(p,`Refreshing ${n.bsm.serverName}...`);const x=await bsmCall("get_server_summary_api_server__server_name__summary_get",{path:{server_name:n.bsm.serverName}});if(x?.name)putBsmCache([x]);later(()=>nodeDetail(p,n,parent))}catch(e){err(p,`BSM refresh failed: ${e?.message??e}`)}}
function getBsmSelf(){return clean(world.getDynamicProperty(BSM_SELF_KEY)??"")}
function setBsmSelf(name,actor){world.setDynamicProperty(BSM_SELF_KEY,clean(name));audit(actor,"bsm-self",clean(name)||"none")}
function bsmWsUrl(){return bsmApiState.wsUrl||"Managed by BSM API addon"}
const wsState={client:null,state:"disconnected",authenticated:false,lastEvent:0,lastTopic:"",lastError:"",retries:0,reconnectRun:null,topics:new Set(),tasks:new Map(),activity:[],players:new Map()};
function saveWsState(){try{world.setDynamicProperty(BSM_WS_KEY,JSON.stringify({state:wsState.state,authenticated:wsState.authenticated,lastEvent:wsState.lastEvent,lastTopic:wsState.lastTopic,lastError:wsState.lastError,retries:wsState.retries,updated:Date.now()}))}catch{}}
function bsmWsSubscribe(topic){if(!topic)return;wsState.topics.add(topic);system.sendScriptEvent("bsmapi:control",JSON.stringify({action:"subscribe",topic}))}
function bsmWsSubscribeAll(){bsmWsSubscribe("*");const d=getPublished();for(const n of d.nodes)if(n.type==="server"&&n.bsm?.serverName)bsmWsSubscribe(`resource-monitor:${n.bsm.serverName}`)}
function cachePatch(name,patch){if(!name)return;const c=parse(world.getDynamicProperty(BSM_CACHE_KEY),{});c[name]={...(c[name]??{name}),...patch,name,updated:Date.now()};world.setDynamicProperty(BSM_CACHE_KEY,JSON.stringify(c))}
function eventServerName(m){const d=m?.data??{};return clean(d.server_name??d.serverName??d.name??d.server??m.server_name??"")}
function addActivity(topic,name,data){wsState.activity.unshift({time:Date.now(),topic,name,data});wsState.activity=wsState.activity.slice(0,80)}
function rebuildPlayerIndex(){wsState.players.clear();const c=parse(world.getDynamicProperty(BSM_CACHE_KEY),{});for(const [server,x] of Object.entries(c))for(const pl of x.players??[])if(pl?.xuid)wsState.players.set(`${pl.xuid}`,{name:pl.name??"Unknown",xuid:`${pl.xuid}`,server,updated:x.updated??Date.now()})}
function applyServerSnapshot(s){if(!s?.name)return;cachePatch(s.name,{status:s.status,version:s.version,player_count:Number(s.player_count??0),players:Array.isArray(s.players)?s.players:[]});rebuildPlayerIndex()}
function handleBsmWsMessage(raw){let m;try{m=typeof raw==="string"?JSON.parse(raw):raw}catch{return}wsState.lastEvent=Date.now();const topic=clean(m.topic??m.type??"message");wsState.lastTopic=topic;const data=m.data??m;if(data?.name&&("status" in data||"player_count" in data||Array.isArray(data.players)))applyServerSnapshot(data);if(m.type==="task_update"||topic.startsWith("task:")){const id=clean(topic).replace(/^task:/,"")||clean(data.task_id);wsState.tasks.set(id,{...data,updated:Date.now()});saveWsState();return}const name=eventServerName(m);if(topic.startsWith("resource-monitor:")){const n=topic.slice("resource-monitor:".length);cachePatch(n,{resources:data});addActivity(topic,n,data)}else if((topic.startsWith("event:")||topic.startsWith("ws_event:"))&&name){const event=topic.replace(/^(event:|ws_event:)/,"");addActivity(event,name,data);if(event.includes("players_change")){cachePatch(name,{player_count:Number(data.player_count??0),players:Array.isArray(data.players)?data.players:[]});rebuildPlayerIndex()}else if(event.includes("status_change")){cachePatch(name,{status:data.status??data.new_status??data.server_status})}else if(event.includes("server_start")){cachePatch(name,{status:"RUNNING"})}else if(event.includes("server_stop")){cachePatch(name,{status:"STOPPED",player_count:0,players:[]});rebuildPlayerIndex()}else if(event.includes("server_update")||event.includes("properties_change"))system.run(()=>bsmCall("get_server_summary_api_server__server_name__summary_get",{path:{server_name:name}}).then(x=>{if(x?.name)putBsmCache([x])}).catch(()=>{}))}saveWsState()}
async function bsmWsConnect(force=false){system.sendScriptEvent("bsmapi:control",JSON.stringify({action:"reconnect"}));if(!force)system.sendScriptEvent("bsmapi:control",JSON.stringify({action:"status"}));return true}
function bsmWsDisconnect(){system.sendScriptEvent("bsmapi:control",JSON.stringify({action:"disconnect"}));wsState.state="disconnected";wsState.authenticated=false;saveWsState()}
async function reconcileBsm(){try{await fetchBsmServers();rebuildPlayerIndex();bsmWsSubscribeAll();return true}catch{return false}}
system.afterEvents.scriptEventReceive.subscribe(ev=>{if(ev.id==="bsmapi:response"){const r=receiveBsmChunk("response",ev.message);if(!r)return;const p=bsmPending.get(r.id);if(!p)return;bsmPending.delete(r.id);system.clearRun(p.timeout);r.ok?p.resolve(r.data):p.reject(Object.assign(Error(r.error||"BSM API request failed"),{status:r.status,data:r.data}))}else if(ev.id==="bsmapi:event"){const x=receiveBsmChunk("event",ev.message);if(x?.raw)handleBsmWsMessage(x.raw)}else if(ev.id==="bsmapi:status"){const x=receiveBsmChunk("status",ev.message);if(!x)return;Object.assign(bsmApiState,x,{available:true});wsState.state=x.state??wsState.state;wsState.authenticated=!!x.authenticated;wsState.lastError=x.lastError??"";saveWsState()}});

function showBsmSelfSelector(p){fetchBsmServers().then(list=>{const current=getBsmSelf();const f=new CustomForm(p,"§b§lThis Server").label("§7Select which BSM server this behavior pack is running on. Players will not be offered that server as a transfer destination.").divider();for(const x of list)f.button(`${x.name}${x.name===current?" (Current)":""}`,()=>{setBsmSelf(x.name,p);info(p,`This server is now ${x.name}.`);later(()=>showBsmAdmin(p))});if(current)f.button("Clear Selection",()=>{setBsmSelf("",p);later(()=>showBsmAdmin(p))});f.divider().button("Back",()=>later(()=>showBsmAdmin(p))).closeButton().show().catch(e=>console.warn(`[${PACK}] self selector failed: ${e}`))}).catch(e=>err(p,`Could not load BSM servers: ${e?.message??e}`))}
function showBsmLiveDiagnostics(p){const saved=parse(world.getDynamicProperty(BSM_WS_KEY),{}),age=saved.lastEvent?Math.max(0,Math.floor((Date.now()-saved.lastEvent)/1000)):null;new CustomForm(p,"§b§lLive Connection").header(saved.authenticated?"§a§lWEBSOCKET LIVE":"§e§lWEBSOCKET NOT LIVE").label(`§fState: §b${saved.state??wsState.state}`).label(`§fEndpoint: §7${bsmWsUrl()||"not configured"}`).label(`§fSelf server: §a${getBsmSelf()||"not selected"}`).label(`§fLast topic: §7${saved.lastTopic||"none"}`).label(`§fLast event: §7${age===null?"never":`${age}s ago`}`).label(saved.lastError?`§cLast error: ${saved.lastError}`:"§aNo socket error recorded.").divider().button("Reconnect WebSocket",()=>{bsmWsDisconnect();bsmWsConnect(true);later(()=>showBsmAdmin(p))}).button("HTTP Reconcile Now",()=>{reconcileBsm().then(ok=>info(p,ok?"BSM cache reconciled.":"BSM reconciliation failed."));later(()=>showBsmAdmin(p))}).button("Back",()=>later(()=>showBsmAdmin(p))).closeButton().show().catch(e=>console.warn(`[${PACK}] diagnostics UI failed: ${e}`))}
function showBsmPlayers(p){const f=new CustomForm(p,"§b§lNetwork Players").label(`§f${wsState.players.size} player(s) currently indexed from BSM live state.`).divider();for(const x of [...wsState.players.values()].sort((a,b)=>a.name.localeCompare(b.name)))f.header(`§a${x.name}`).label(`§7Server: §f${x.server} §8• §7XUID: ${x.xuid}`).button(`Open ${x.server}`,()=>{const n=getPublished().nodes.find(n=>n.type==="server"&&n.bsm?.serverName===x.server);if(n)nodeDetail(p,n,n.parentId);else err(p,"That BSM server is not published as a destination.")});if(!wsState.players.size)f.label("§7No live player snapshots received yet.");f.divider().button("Back",()=>later(()=>showBsmAdmin(p))).closeButton().show().catch(e=>console.warn(`[${PACK}] players UI failed: ${e}`))}
function showBsmActivity(p){const f=new CustomForm(p,"§e§lNetwork Activity").label("§7Recent BSM WebSocket events received by this server.").divider();for(const x of wsState.activity.slice(0,30)){const age=Math.max(0,Math.floor((Date.now()-x.time)/1000));f.header(`§b${x.name||"BSM"}`).label(`§f${x.topic} §8• §7${age}s ago`)}if(!wsState.activity.length)f.label("§7No live events received yet.");f.divider().button("Back",()=>later(()=>showBsmAdmin(p))).closeButton().show().catch(e=>console.warn(`[${PACK}] activity UI failed: ${e}`))}
async function bsmImportServer(p,server){try{const name=clean(server?.name);if(!name)throw Error("BSM server has no name.");const props=await fetchBsmProperties(name);const port=Number(props["server-port"]??props.server_port??19132);const d=getDraft();let n=d.nodes.find(x=>x.type==="server"&&x.bsm?.serverName===name);const created=!n;if(!n){const base=idFrom(name);n={id:unique(d.nodes,base),type:"server",parentId:null,name,description:"Managed by Bedrock Server Manager",order:d.nodes.filter(x=>(x.parentId??null)===null).length,enabled:true,tags:["bsm"],region:"",gameMode:"",recommended:false,maintenance:false,requirements:{},cooldownSeconds:2,bsm:{serverName:name}};d.nodes.push(n)}n.name=n.name||name;n.hostname=n.hostname||bsmTransferHost();n.port=Number.isInteger(port)&&port>0&&port<=65535?port:19132;n.bsm={...(n.bsm??{}),serverName:name};saveDraft(d);audit(p,created?"bsm-import":"bsm-update",name);info(p,`${name}: ${created?"imported into":"updated in"} draft.`);later(()=>bsmServerAdmin(p,{...server,...getBsmCache(name),name}))}catch(e){err(p,`Import failed: ${e?.message??e}`)}}
async function bsmDiscover(p){try{const list=await fetchBsmServers(),f=new CustomForm(p,"§b§lBSM Server Directory").label(`§f${list.length} server(s) reported by BSM.`).label("§7Select a server to inspect, control, or import it into the Transfer UI draft.").divider();for(const x of list){const c=getBsmCache(x.name)??x;f.button(`${x.name}\n${c.status??"UNKNOWN"} • ${c.player_count??0} player(s)`,()=>bsmServerAdmin(p,c))}if(!list.length)f.label("§7No BSM servers were returned.");f.divider().button("Refresh",()=>bsmDiscover(p)).button("Back",()=>showBsmAdmin(p)).closeButton().show()}catch(e){err(p,`Server directory failed: ${e?.message??e}`)}}
async function bsmHealth(p){try{const list=await fetchBsmServers(),f=new CustomForm(p,"§a§lNetwork Health").label("§7Live BSM server state. WebSocket snapshots are preferred when available.").divider();for(const x of list){const c=getBsmCache(x.name)??x,st=`${c.status??"UNKNOWN"}`.toUpperCase();f.header(`${st==="RUNNING"?"§a":st==="STOPPED"?"§c":"§e"}${x.name}`).label(`§fStatus: §b${st} §8• §fPlayers: §b${c.player_count??0} §8• §fVersion: §7${c.version??"unknown"}`).button(`Manage ${x.name}`,()=>bsmServerAdmin(p,c))}if(!list.length)f.label("§7No servers reported.");f.divider().button("Refresh",()=>bsmHealth(p)).button("Back",()=>showBsmAdmin(p)).closeButton().show()}catch(e){err(p,`Network health failed: ${e?.message??e}`)}}
async function bsmRefreshMenu(p){try{info(p,"Reconciling BSM state...");await reconcileBsm();info(p,"BSM state reconciled.");later(()=>showBsmAdmin(p))}catch(e){err(p,`Reconcile failed: ${e?.message??e}`);later(()=>showBsmAdmin(p))}}
function bsmServerAdmin(p,server){const name=clean(server?.name??server?.server_name);if(!name)return err(p,"BSM server name is missing.");const c=getBsmCache(name)??server??{},st=`${c.status??"UNKNOWN"}`.toUpperCase(),running=st==="RUNNING",isSelf=name===getBsmSelf(),linked=getDraft().nodes.some(n=>n.type==="server"&&n.bsm?.serverName===name);const f=new CustomForm(p,`§b§l${name}`).header(running?"§a§lRUNNING":`§e§l${st}`).label(`§fPlayers: §b${c.player_count??0} §8• §fVersion: §7${c.version??"unknown"}`).label(`${isSelf?"§aThis is the current server.":"§7Not selected as this server."} §8• ${linked?"§aLinked to draft":"§eNot linked to draft"}`).divider().header("§b§lServer Management").button("Overview & Performance",()=>bsmOverview(p,name)).button("Properties",()=>bsmProperties(p,name)).button("Send Command",()=>bsmCommand(p,name)).button("Backups",()=>bsmBackups(p,name)).button("Players & Access",()=>bsmAccess(p,name)).button("Add-ons",()=>bsmAddons(p,name)).button("World Export",()=>bsmWorld(p,name)).divider().header("§e§lLifecycle").button("Start Server",()=>bsmConfirmAction(p,name,"start")).button("Stop Server",()=>bsmConfirmAction(p,name,"stop")).button("Restart Server",()=>bsmConfirmAction(p,name,"restart")).button("Update Server",()=>bsmConfirmAction(p,name,"update")).divider().header("§d§lTransfer UI").button(linked?"Update Draft Destination":"Import to Draft",()=>bsmImportServer(p,c)).button(isSelf?"This Server (Selected)":"Select as This Server",()=>{setBsmSelf(name,p);info(p,`This server is now ${name}.`);later(()=>bsmServerAdmin(p,c))}).divider().button("Refresh",()=>bsmRefreshServerAdmin(p,name)).button("Back to Directory",()=>bsmDiscover(p)).closeButton().show().catch(e=>console.warn(`[${PACK}] BSM server UI failed: ${e}`))}
function showBsmAdmin(p){if(!isAdmin(p))return;const c=bsmConfig(),saved=parse(world.getDynamicProperty(BSM_WS_KEY),{}),live=!!saved.authenticated;const f=new CustomForm(p,"§b§lBedrock Server Manager").header("§b§lNetwork Console").label(`§fHTTP: ${c.url?"§aConfigured":"§cNot configured"} §8• §fWebSocket: ${live?"§aLIVE":`§e${saved.state??"offline"}`}`).label(`§fThis server: §a${getBsmSelf()||"Not selected"} §8• §fTransfer host: §7${c.host}`).divider().header("§a§lNetwork").button("Server Directory",()=>bsmDiscover(p)).button("Network Health",()=>bsmHealth(p)).button("Network Players",()=>showBsmPlayers(p)).button("Network Activity",()=>showBsmActivity(p)).button("Active BSM Tasks",()=>showBsmTasks(p)).button("Refresh / Reconcile",()=>bsmRefreshMenu(p)).divider().header("§e§lConfiguration").button("Select This Server",()=>showBsmSelfSelector(p)).button("Live Connection & Diagnostics",()=>showBsmLiveDiagnostics(p)).button("Integration Capabilities",()=>showBsmCapabilities(p)).label("§7BSM networking and credentials are owned by the separate BSM API addon. Transfer UI does not handle the JWT.").divider().header("§d§lNavigation").button("Manage Destinations",()=>later(()=>adminNodes(p,null))).button("Preview Player Network",()=>showFolder(p)).divider().button("Back",()=>later(()=>showAdmin(p))).closeButton().show().catch(e=>console.warn(`[${PACK}] DDUI show failed: ${e}`))}
async function showBsmTasks(p){try{const r=await bsmCall("list_tasks_api_tasks_list_get"),items=Array.isArray(r)?r:(r?.tasks??r?.items??[]),f=new CustomForm(p,"§e§lActive BSM Tasks").label("§7Native BSM background-task state. WebSocket task updates are still used for live progress.").divider();if(!items.length)f.label("§7No tasks reported.");for(const t of items.slice(0,30))f.header(`§b${t.task_id??t.id??"Task"}`).label(`§7${JSON.stringify(t).slice(0,650)}`);f.divider().button("Refresh",()=>showBsmTasks(p)).button("Back",()=>showBsmAdmin(p)).closeButton().show()}catch(e){err(p,`Tasks failed: ${e?.message??e}`)}}
async function showBsmCapabilities(p){try{const [app,plugins]=await Promise.all([bsmCall("get_system_info_api_info_get"),bsmCall("get_plugins_status_api_plugins_get")]),f=new CustomForm(p,"§b§lBSM API").header("§a§lNATIVE API CONNECTED").label("§7Transfer UI calls the separate BSM API addon by OpenAPI operationId. The BSM API addon owns HTTP, models, authentication, and WebSocket state.").header("§e§lBSM").label(`§7${JSON.stringify(app?.info??app).slice(0,1200)}`).header("§d§lPlugins").label(`§7${JSON.stringify(plugins?.plugins??plugins).slice(0,900)}`).divider().button("Back",()=>showBsmAdmin(p)).closeButton();f.show()}catch(e){err(p,`BSM API unavailable: ${e?.message??e}`)}}
async function bsmOverview(p,name){try{const n=encodeURIComponent(name),[summary,status,process,settings,valid]=await Promise.all([bsmCall("get_server_summary_api_server__server_name__summary_get",{path:{server_name:name}}),bsmCall("get_server_running_status_api_server__server_name__status_get",{path:{server_name:name}}),bsmCall("get_server_process_info_api_server__server_name__process_info_get",{path:{server_name:name}}),bsmCall("get_server_settings_api_server__server_name__settings_get_get",{path:{server_name:name}}),bsmCall("get_validate_server_api_server__server_name__validate_get",{path:{server_name:name}})]),f=new CustomForm(p,`§b§l${name} Overview`);f.header("§a§lLive Server").label(`§fStatus: §b${summary?.status??(status?.running?"RUNNING":"STOPPED")}`).label(`§fPlayers: §b${summary?.player_count??0} §8• §fVersion: §7${summary?.version??"unknown"}`).header("§e§lPerformance").label(`§7${JSON.stringify(process?.process_info??process).slice(0,900)}`).header("§d§lBSM Settings").label(`§7${JSON.stringify(settings?.settings??settings).slice(0,700)}`).label(`§fInstallation validation: §7${valid?.status??JSON.stringify(valid).slice(0,220)}`).divider().button("Back",()=>bsmRefreshServerAdmin(p,name)).closeButton().show()}catch(e){err(p,`Overview failed: ${e?.message??e}`)}}
async function bsmProperties(p,name){try{const r=await bsmCall("get_properties_api_server__server_name__properties_get_get",{path:{server_name:name}}),props=r?.properties??{},keys=["server-name","server-port","max-players","gamemode","difficulty","allow-cheats","allow-list","view-distance","tick-distance"],f=new CustomForm(p,`§e§lProperties: ${name}`).label("§7Common server.properties values from BSM's native properties endpoint.").divider();for(const k of keys)if(props[k]!==undefined)f.label(`§f${k}: §b${props[k]}`);f.divider().button("Refresh",()=>bsmProperties(p,name)).button("Back",()=>bsmRefreshServerAdmin(p,name)).closeButton().show()}catch(e){err(p,`Properties failed: ${e?.message??e}`)}}
function bsmCommand(p,name){const cmd=new ObservableString("",{clientWritable:true});new CustomForm(p,`§c§lCommand: ${name}`).label("§7Runs a BDS command through BSM. Do not include a leading slash.").textField("Command",cmd).button("Send",async()=>{try{const c=clean(cmd.getData());if(!c)return err(p,"Enter a command.");await bsmCall("post_send_command_api_server__server_name__send_command_post",{path:{server_name:name},body:{command:c}});audit(p,"bsm-command",`${name}: ${c}`);info(p,"Command sent.");later(()=>bsmRefreshServerAdmin(p,name))}catch(e){err(p,`Command failed: ${e?.message??e}`)}}).button("Back",()=>bsmRefreshServerAdmin(p,name)).closeButton().show()}
async function bsmBackups(p,name){try{const n=encodeURIComponent(name),r=await bsmCall("get_list_server_backups_api_server__server_name__backup_list__backup_type__get",{path:{server_name:name,backup_type:"world"}}),items=asList(r),f=new CustomForm(p,`§d§lBackups: ${name}`).label(`§f${items.length} world backup(s) reported.`).divider();for(const b of items.slice(0,15))f.label(`§7${typeof b==="string"?b:(b.name??b.path??JSON.stringify(b)).toString().slice(0,150)}`);f.divider().button("Create Full Backup",()=>bsmConfirmBackup(p,name)).button("Create World Backup",()=>bsmConfirmNativeAction(p,name,"backup-world","Create a world backup?","post_backup_action_api_server__server_name__backup_action_post",{body:{backup_type:"world"}})).button("Prune Old Backups",()=>bsmConfirmNativeAction(p,name,"prune-backups","Prune backups using BSM retention settings?","put_prune_backups_api_server__server_name__backups_prune_put")).button("Back",()=>bsmRefreshServerAdmin(p,name)).closeButton().show()}catch(e){err(p,`Backups failed: ${e?.message??e}`)}}
async function bsmAccess(p,name){try{const n=encodeURIComponent(name),[a,per,bans]=await Promise.all([bsmCall("get_allowlist_api_server__server_name__allowlist_get_get",{path:{server_name:name}}),bsmCall("get_permissions_api_server__server_name__permissions_get_get",{path:{server_name:name}}),bsmCall("get_server_bans_api_server__server_name__bans_get_get",{path:{server_name:name}})]),f=new CustomForm(p,`§b§lPlayers & Access: ${name}`).header("§a§lAllowlist").label(`§7${JSON.stringify(a?.players??a).slice(0,1000)}`).header("§e§lPermissions").label(`§7${JSON.stringify(per?.permissions??per).slice(0,1000)}`).header("§c§lBans").label(`§7${JSON.stringify(bans).slice(0,1000)}`).divider().button("Refresh",()=>bsmAccess(p,name)).button("Back",()=>bsmRefreshServerAdmin(p,name)).closeButton();f.show()}catch(e){err(p,`Player access failed: ${e?.message??e}`)}}
async function bsmAddons(p,name){try{const r=await bsmCall("get_server_addons_api_server__server_name__addons_get",{path:{server_name:name}}),groups=r?.addons??{},items=[...(groups.behavior_packs??[]),...(groups.resource_packs??[])],f=new CustomForm(p,`§d§lAdd-ons: ${name}`).label(`§f${items.length} installed add-on record(s).`).divider();for(const a of items.slice(0,30))f.header(`§b${a.name??a.uuid??"Add-on"}`).label(`§7${JSON.stringify(a).slice(0,500)}`);f.divider().button("Refresh",()=>bsmAddons(p,name)).button("Back",()=>bsmRefreshServerAdmin(p,name)).closeButton().show()}catch(e){err(p,`Add-ons failed: ${e?.message??e}`)}}
async function bsmWorld(p,name){const n=encodeURIComponent(name);new CustomForm(p,`§a§lWorld: ${name}`).label("§7BSM's official API exposes world export as a background task. Destructive world install/reset operations remain intentionally excluded from Transfer UI.").divider().button("Export World",()=>bsmConfirmNativeAction(p,name,"world-export","Export the active world to an .mcworld file?","post_world_export_api_server__server_name__world_export_post")).button("Back",()=>bsmRefreshServerAdmin(p,name)).closeButton().show()}
function bsmConfirmNativeAction(p,name,a,body,operationId,args={}){new MessageFormData().title(`BSM ${a}`).body(body).button1("Confirm").button2("Cancel").show(p).then(async r=>{if(!r.canceled&&r.selection===0){try{const result=await bsmCall(operationId,{...args,path:{...(args.path||{}),server_name:name}});if(result?.task_id)wsState.tasks.set(result.task_id,{status:"requested",message:`${a} ${name}`,updated:Date.now()});audit(p,`bsm-${a}`,name);info(p,`${name}: ${a} requested.`)}catch(e){err(p,`BSM action failed: ${e?.message??e}`)}}later(()=>bsmRefreshServerAdmin(p,name))})}
async function bsmRefreshServerAdmin(p,name){try{const x=await bsmCall("get_server_summary_api_server__server_name__summary_get",{path:{server_name:name}});putBsmCache([x]);later(()=>bsmServerAdmin(p,x))}catch(e){err(p,`Refresh failed: ${e?.message??e}`)}}
function bsmConfirmAction(p,name,action){const ids={start:"post_start_server_api_server__server_name__start_post",stop:"post_stop_server_api_server__server_name__stop_post",restart:"post_restart_server_api_server__server_name__restart_post",update:"post_update_server_api_server__server_name__update_post"};new MessageFormData().title(`BSM ${action}`).body(`${action[0].toUpperCase()+action.slice(1)} ${name}?`).button1("Confirm").button2("Cancel").show(p).then(async r=>{if(!r.canceled&&r.selection===0){try{const result=await bsmCall(ids[action],{path:{server_name:name}});if(result?.task_id)wsState.tasks.set(result.task_id,{status:"requested",message:`${action} ${name}`,updated:Date.now()});audit(p,`bsm-${action}`,name);info(p,`${name}: ${action} requested.`)}catch(e){err(p,`BSM action failed: ${e?.message??e}`)}}later(()=>showBsmAdmin(p))}).catch(e=>console.warn(`[${PACK}] BSM confirmation failed: ${e}`))}
function bsmConfirmBackup(p,name){new MessageFormData().title("BSM Backup").body(`Create a full backup of ${name}?`).button1("Backup").button2("Cancel").show(p).then(async r=>{if(!r.canceled&&r.selection===0){try{const result=await bsmCall("post_backup_action_api_server__server_name__backup_action_post",{path:{server_name:name},body:{backup_type:"all"}});if(result?.task_id)wsState.tasks.set(result.task_id,{status:"requested",message:`backup ${name}`,updated:Date.now()});audit(p,"bsm-backup",name);info(p,`${name}: backup requested.`)}catch(e){err(p,`Backup failed: ${e?.message??e}`)}}later(()=>showBsmAdmin(p))}).catch(e=>console.warn(`[${PACK}] BSM backup confirmation failed: ${e}`))}

world.beforeEvents.itemUse.subscribe(e=>{const p=e.source;if(e.itemStack?.typeId===getPublished().settings.openerItem)later(()=>showFolder(p))});
world.afterEvents.worldLoad.subscribe(()=>{try{if(world.getDynamicProperty(DATA_KEY)===undefined){savePublished(clone(DEF));world.setDynamicProperty(DRAFT_KEY,JSON.stringify(DEF))}else{const migrated=getPublished();if(parse(world.getDynamicProperty(DATA_KEY),{}).version!==DATA_VERSION){migrated.revision=(migrated.revision??0)+1;savePublished(migrated,"system","schema-migrate");world.setDynamicProperty(DRAFT_KEY,JSON.stringify(migrated))}}console.log(`[${PACK}] v3.0.0 loaded: navigation + optional BSM API addon integration.`);system.runTimeout(()=>{system.sendScriptEvent("bsmapi:control",JSON.stringify({action:"status"}));bsmWsConnect().catch(()=>{});system.runInterval(()=>{if(!wsState.authenticated)bsmWsConnect().catch(()=>{});else reconcileBsm().catch(()=>{})},1200)},40)}catch(e){console.error(`[${PACK}] initialization failed`,e)}});
